const marker='GBrain MCP roundtrip synthetic marker '+crypto.randomUUID();
const saved=await client.callTool({name:'remember',arguments:{fact:marker,entity:'concepts/gbrain-install-verification',provenance:'install-check',content_origin:'inferred',_meta:{hot_memory:'off'}}});
console.log(JSON.stringify({stage:'remember',response:saved}));
if(saved.isError) throw new Error('MCP remember failed');
const facts=await client.callTool({name:'recall',arguments:{entity:'concepts/gbrain-install-verification',_meta:{hot_memory:'off'}}});
if(facts.isError || !JSON.stringify(facts).includes(marker)) throw new Error('MCP roundtrip failed');
const payload=JSON.parse(facts.content.find(c=>c.type==='text').text);
const fact=payload.facts.find(f=>f.fact.includes(marker));
const forgetTool=list.tools.find(t=>t.name==='forget');
const key=forgetTool.inputSchema.properties.fact_id ? 'fact_id' : 'id';
const forgotten=await client.callTool({name:'forget',arguments:{[key]:String(fact.fact_id??fact.id),reason:'install-check fixture cleanup',_meta:{hot_memory:'off'}}});
console.log(JSON.stringify({stage:'forget',response:forgotten}));
if(forgotten.isError) throw new Error('MCP fixture cleanup failed');
const clean=await client.callTool({name:'recall',arguments:{entity:'concepts/gbrain-install-verification',_meta:{hot_memory:'off'}}});
if(JSON.stringify(clean).includes(marker)) throw new Error('MCP fixture still active');
console.log(JSON.stringify({stage:'verification',ok:true,roundtrip:'MCP remember -> recall -> forget -> recall omission',scope:'standalone stdio MCP, not native OpenClaw conversation'}));

